SET NOCOUNT ON;
CREATE TABLE #r (id varchar(40), res nvarchar(400));
BEGIN TRY INSERT #r SELECT 'obj2', CONCAT(COUNT(*),':',MAX(a)) FROM OPENJSON(N'{"a":"x","b":2}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('obj2','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'obj-onlyb', CONCAT(COUNT(*),':',MAX(a)) FROM OPENJSON(N'{"b":2}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('obj-onlyb','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'obj-null', CONCAT(COUNT(*),':',MAX(a)) FROM OPENJSON(N'{"a":null}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('obj-null','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'arr-of-empty', CONCAT(COUNT(*),':',MAX(a)) FROM OPENJSON(N'[{}, {}]') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('arr-of-empty','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'nested-arr', CONCAT(COUNT(*),':',MAX(a)) FROM OPENJSON(N'[[{"a":"x"}]]') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('nested-arr','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'order', STRING_AGG(a,',') FROM OPENJSON(N'[{"a":"3"},{"a":"1"},{"a":"2"}]') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('order','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'path-root', CONCAT(COUNT(*),':',MAX(a)) FROM OPENJSON(N'["x","y"]') WITH (a nvarchar(10) '$'); END TRY BEGIN CATCH INSERT #r VALUES('path-root','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'arg-path', CONCAT(COUNT(*),':',MAX(a)) FROM OPENJSON(N'{"t":[{"a":"x"}]}', '$.t') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('arg-path','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'obj-of-obj', CONCAT(COUNT(*),':',MAX(a)) FROM OPENJSON(N'{"x":{"a":"y"},"a":"z"}') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('obj-of-obj','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dup2', a FROM OPENJSON(N'[{"a":"f","b":1,"a":"s"}]') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('dup2','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dup-null', ISNULL(a,'<null>') FROM OPENJSON(N'[{"a":null,"a":"s"}]') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('dup-null','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dup-obj', ISNULL(a,'<null>') FROM OPENJSON(N'[{"a":{},"a":"s"}]') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('dup-obj','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'key-esc', ISNULL(a,'<null>') FROM OPENJSON(N'[{"a":"s"}]') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('key-esc','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'nul-char', CONCAT(LEN(a),'') FROM OPENJSON(N'[{"a":"x\u0000y"}]') WITH (a nvarchar(10)); END TRY BEGIN CATCH INSERT #r VALUES('nul-char','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'num-big', a FROM OPENJSON(N'[{"a":123456789012345678901234567890}]') WITH (a nvarchar(50)); END TRY BEGIN CATCH INSERT #r VALUES('num-big','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'num-neg', a FROM OPENJSON(N'[{"a":-0.0}]') WITH (a nvarchar(50)); END TRY BEGIN CATCH INSERT #r VALUES('num-neg','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'lead-zero', a FROM OPENJSON(N'[{"a":012}]') WITH (a nvarchar(50)); END TRY BEGIN CATCH INSERT #r VALUES('lead-zero','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'trailing', CONCAT(COUNT(*),'') FROM OPENJSON(N'[{"a":1}] x') WITH (a nvarchar(50)); END TRY BEGIN CATCH INSERT #r VALUES('trailing','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-plus', CONCAT(a,'') FROM OPENJSON(N'[{"a":"+5"}]') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-plus','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-tab', CONCAT(a,'') FROM OPENJSON(N'[{"a":"\t5"}]') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-tab','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'int-lead0', CONCAT(a,'') FROM OPENJSON(N'[{"a":"007"}]') WITH (a int); END TRY BEGIN CATCH INSERT #r VALUES('int-lead0','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dec-sp', CONCAT(a,'') FROM OPENJSON(N'[{"a":" 1.5 "}]') WITH (a decimal(18,2)); END TRY BEGIN CATCH INSERT #r VALUES('dec-sp','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dec-empty', ISNULL(CONCAT(a,''),'<null>') FROM OPENJSON(N'[{"a":""}]') WITH (a decimal(18,2)); END TRY BEGIN CATCH INSERT #r VALUES('dec-empty','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dec-dot', CONCAT(a,'') FROM OPENJSON(N'[{"a":".5"}]') WITH (a decimal(18,2)); END TRY BEGIN CATCH INSERT #r VALUES('dec-dot','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'dec-half', CONCAT(a,'') FROM OPENJSON(N'[{"a":0.125}]') WITH (a decimal(18,2)); END TRY BEGIN CATCH INSERT #r VALUES('dec-half','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'date-empty', ISNULL(CONCAT(a,''),'<null>') FROM OPENJSON(N'[{"a":""}]') WITH (a date); END TRY BEGIN CATCH INSERT #r VALUES('date-empty','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'bit-empty', ISNULL(CONCAT(a,''),'<null>') FROM OPENJSON(N'[{"a":""}]') WITH (a bit); END TRY BEGIN CATCH INSERT #r VALUES('bit-empty','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'bit-neg', ISNULL(CONCAT(a,''),'<null>') FROM OPENJSON(N'[{"a":-1}]') WITH (a bit); END TRY BEGIN CATCH INSERT #r VALUES('bit-neg','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'bit-0str', ISNULL(CONCAT(a,''),'<null>') FROM OPENJSON(N'[{"a":"0"}]') WITH (a bit); END TRY BEGIN CATCH INSERT #r VALUES('bit-0str','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'bit-FALSE', ISNULL(CONCAT(a,''),'<null>') FROM OPENJSON(N'[{"a":"FALSE"}]') WITH (a bit); END TRY BEGIN CATCH INSERT #r VALUES('bit-FALSE','ERR '+ERROR_MESSAGE()) END CATCH
BEGIN TRY INSERT #r SELECT 'vb', ISNULL(CONVERT(varchar(40),a,1),'<null>') FROM OPENJSON(N'[{"a":"AQI="}]') WITH (a varbinary(max)); END TRY BEGIN CATCH INSERT #r VALUES('vb','ERR '+ERROR_MESSAGE()) END CATCH
SELECT id + ' => ' + ISNULL(res,'<NULL>') FROM #r;
